SELECT Go.IdP, Go.Cognome, Go.Nome, Scuola.AnnoS, Materia_1.Materia, Prof_4.Cognome, Scuola.Razred, Scuola.Voto, Konservatori.Konservatori, Scuola.Data, Scuola.Livello, LPPrVal.Solsko, Materia_2.Materia, Prof_1.Cognome, LPPrVal.Valutazione, Nastop.Solsko, LNPPr.Skupine, Materia.Materia, Prof.Cognome, Nastop.Organizator, Nastop.Nastop, Nastop.TipNastop, Nastop.Kraj, Nastop.Da, Nastop.A, Sodelo.Solsko, LSPPr.Skupine, Materia_3.Materia, Prof_3.Cognome, Sodelo.Organizator, Sodelo.Pobude, Sodelo.TipPobude, Sodelo.Kraj, Sodelo.Da, Sodelo.A, Tekma.Solsko, LTPPr.Skupine, Materia_4.Materia, Prof_2.Cognome, Tekma.Tekma, Tekma.Kraj, Tekma.Da, Tekma.A, LTPPr.Kat, LTPPr.Nagrada, LTPPr.Toc
FROM (Materia AS Materia_2 RIGHT JOIN ((((((((Prof AS Prof_1 RIGHT JOIN ((((((((([Go] LEFT JOIN LNPPr ON Go.IdP = LNPPr.IdP) LEFT JOIN LPPrVal ON Go.IdP = LPPrVal.IdP) LEFT JOIN LSPPr ON Go.IdP = LSPPr.IdP) LEFT JOIN LTPPr ON Go.IdP = LTPPr.IdP) LEFT JOIN Nastop ON LNPPr.IdN = Nastop.IdN) LEFT JOIN Materia ON LNPPr.IdM = Materia.IdM) LEFT JOIN Sodelo ON LSPPr.IdS = Sodelo.IdS) LEFT JOIN Tekma ON LTPPr.IdT = Tekma.IdT) LEFT JOIN Prof ON LNPPr.IdPr = Prof.IdPr) ON Prof_1.IdPr = LPPrVal.IdPr) LEFT JOIN Prof AS Prof_2 ON LTPPr.IdPr = Prof_2.IdPr) LEFT JOIN Prof AS Prof_3 ON LSPPr.IdPr = Prof_3.IdPr) LEFT JOIN Scuola ON Go.IdP = Scuola.IdP) LEFT JOIN Prof AS Prof_4 ON Scuola.IdPr = Prof_4.IdPr) LEFT JOIN Materia AS Materia_1 ON Scuola.IdM = Materia_1.IdM) LEFT JOIN Materia AS Materia_3 ON LSPPr.IdM = Materia_3.IdM) LEFT JOIN Materia AS Materia_4 ON LTPPr.IdM = Materia_4.IdM) ON Materia_2.IdM = LPPrVal.IdM) LEFT JOIN Konservatori ON Scuola.IdK = Konservatori.IdK;
